import json, os

def aggregate_records(records):
    total_amount = 0
    user_totals = {}
    tag_counts = {}

    for line in records:
        data = json.loads(line)
        user = data.get('user', 'unknown')
        amount = float(data.get('amount', 0))
        items = data.get('items', [])
        tags = data.get('tags', [])

        total_amount += amount
        user_totals[user] = user_totals.get(user, 0) + amount
        for tag in tags:
            tag_counts[tag] = tag_counts.get(tag, 0) + 1

        for item in items:
            item_name = item.get('name', 'unknown')
            if item_name not in user_totals:
                user_totals[item_name] = 0
            user_totals[item_name] += amount

    return {
        'total_amount': total_amount,
        'user_totals': user_totals,
        'tag_counts': tag_counts
    }

def main():
    if not os.path.exists('sample_records.jsonl'):
        print('No sample_records.jsonl found')
        return

    with open('sample_records.jsonl', 'r') as f:
        results = aggregate_records(f)

    print(f'Total amount: {results['total_amount']}')
    print('User totals:')
    for user, total in results['user_totals'].items():
        print(f'  {user}: {total}')
    print('Tag counts:')
    for tag, count in results['tag_counts'].items():
        print(f'  {tag}: {count}')

if __name__ == '__main__':
    main()

